import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bool status, address otherCaller) public {
        vm.assume(caller != address(0) && otherCaller != address(0));
        // Owner is initially address(0) - set owner to a known address
        vm.prank(address(0));
        // Not needed: owner can't be changed from this contract, so owner is address(0) (unlikely but works)
