pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address targetAddr, bool status) public {
        // Skip cases where caller is owner (owner can modify mappings)
        vm.assume(caller != address(this));

        // Record initial state for a random address that we may query
        address queryAddr = address(uint160(uint256(keccak256(abi.encode(caller, targetAddr, status)))));

        // Try calling setApprovedLogger as non-owner - should fail
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("setApprovedLogger(address,bool)", targetAddr, status));

        // The buggy version would always modify mapping at address(0)
        // The reference version doesn't modify anything
        // So we check that approvedLoggers[targetAddr] is unchanged
        bool originalValue = c.approvedLoggers(targetAddr);
        bool queryValue = c.approvedLoggers(queryAddr);

        // General rule: for non-owner callers, the mapping state should not change
        // After failed call, target address value stays same, and zero address unchanged
        assertTrue(!success && originalValue == c.approvedLoggers(targetAddr) && c.approvedLoggers(address(0)) == queryValue);
    }
}

