import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address logger, bool status, address checkAddr) public {
        // Restrict: caller must be owner (the contract deployer)
        vm.assume(caller == address(this));

        // First, ensure checkAddr wasn't set to true by a previous call.
        // We'll set it to false before the test.
        if (status == false) {
            // If status is false, the reference sets approvedLoggers[logger] = false.
            // The bug would set it to true regardless of status.
            // So after the call, for the same logger, if status == false:
            // reference: approvedToLog(logger) == false
            // bug: approvedToLog(logger) == true
            // The rule: when status is false, approvedToLog(logger) should be false.

            // But we also need to check an address that was never set: checkAddr.
            // Before any setApprovedLogger, approvedToLog(checkAddr) returns false (default).
            // After the call with status=false, if checkAddr != logger, the mapping for checkAddr is unchanged.
            // Bug doesn't affect it, so it's still false in both.
            // Choose checkAddr to be an address that was not set and is not logger.
            // That won't break the bug. 
            // Instead, we use the same address for logger and checkAddr.
        }

        // Use the same address for logger and checkAddr to directly test the mapping for that address.
        address target = logger;

        // Before the call, the mapping for target should be false (default or previously set).
        // We'll call setApprovedLogger with status = false for the reference.
        // Bug will set to true regardless.
        // So we compare the return value of approvedToLog(target) after the call:
        // For reference: return == false
        // For bug: return == true

        c.setApprovedLogger(target, false);

        bool result = c.approvedToLog(target);

        // The general rule: after calling setApprovedLogger(target, false), approvedToLog(target) must be false.
        assertTrue(result == false);
    }
}

